package android.database.sqlite;import android.content.Context;import android.database.Cursor;public abstract class SQLiteOpenHelper implements AutoCloseable {final Context c;final String name;final int version;SQLiteDatabase db;public SQLiteOpenHelper(Context c,String name,Object factory,int version){this.c=c;this.name=name;this.version=version;}public synchronized SQLiteDatabase getWritableDatabase(){if(db!=null)return db;db=new SQLiteDatabase(c.getDatabasePath(name));int old;try(Cursor cur=db.rawQuery("PRAGMA user_version",null)){cur.moveToFirst();old=cur.getInt(0);}if(old!=version){db.beginTransaction();try{if(old==0)onCreate(db);else onUpgrade(db,old,version);db.execSQL("PRAGMA user_version="+version);db.setTransactionSuccessful();}catch(RuntimeException e){db.endTransaction();db.close();db=null;throw e;}db.endTransaction();}onOpen(db);return db;}public void setWriteAheadLoggingEnabled(boolean on){}public SQLiteDatabase getReadableDatabase(){return getWritableDatabase();}public synchronized void close(){if(db!=null){db.close();db=null;}}public void onOpen(SQLiteDatabase db){}public abstract void onCreate(SQLiteDatabase d);public abstract void onUpgrade(SQLiteDatabase d,int old,int next);}